  ('35d27812-21c2-4caa-80a6-576171e80ebb', 'e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', null, 'topic'::public.curated_course_node_type, 'Statistical Thinking, Questions, and Data Quality', 'Statistics begins with a decision, not a formula. This unit teaches students to frame answerable questions, understand how data were generated, and recognize when evidence is too weak or biased for the intended decision.', 0),
