insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'textbook'::public.curated_course_resource_kind, 'Introductory Business Statistics', 'https://openstax.org/details/books/introductory-business-statistics', 'OpenStax. Free business-context foundation for descriptive statistics, probability, inference, regression, and applications.', 0),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'textbook'::public.curated_course_resource_kind, 'OpenIntro Statistics', 'https://www.openintro.org/book/os/', 'Modern open text, datasets, simulation-based explanations, and applied exercises.', 1),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'textbook'::public.curated_course_resource_kind, 'Applied Statistics and Probability for Engineers', 'Wiley', 'Montgomery and Runger. Probability, inference, regression, DOE, quality, and engineering applications.', 2),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'textbook'::public.curated_course_resource_kind, 'Probability and Statistics for Engineering and the Sciences', 'Cengage', 'Devore. Rigorous distributions, estimation, tests, regression, and engineering examples.', 3),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'textbook'::public.curated_course_resource_kind, 'Intuitive Biostatistics', 'Oxford University Press', 'Harvey Motulsky. Interpretation-centered guide for biomedical, kinesiology, and health research.', 4),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'textbook'::public.curated_course_resource_kind, 'Design and Analysis of Experiments', 'Wiley', 'Douglas C. Montgomery. Forward reference for factorial design, response surfaces, and industrial experimentation.', 5),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'website'::public.curated_course_resource_kind, 'NIST/SEMATECH e-Handbook of Statistical Methods', 'https://www.itl.nist.gov/div898/handbook/', 'Engineering measurement, process modeling, DOE, SPC, reliability, and case studies.', 6),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'website'::public.curated_course_resource_kind, 'MIT 18.05 Introduction to Probability and Statistics', 'https://ocw.mit.edu/courses/18-05-introduction-to-probability-and-statistics-spring-2022/', 'Probability, Bayesian and frequentist inference, bootstrap, tests, regression, R, and active learning.', 7),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'website'::public.curated_course_resource_kind, 'MIT 18.443 Statistics for Applications', 'https://ocw.mit.edu/courses/18-443-statistics-for-applications-spring-2015/', 'Inference, ANOVA, nonparametrics, regression, Bayesian statistics, decision theory, and R.', 8),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'website'::public.curated_course_resource_kind, 'MIT 15.060 Data, Models, and Decisions', 'https://ocw.mit.edu/courses/15-060-data-models-and-decisions-fall-2014/', 'Cases, probability, simulation, regression, optimization awareness, and managerial recommendations.', 9),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'website'::public.curated_course_resource_kind, 'Seeing Theory', 'https://seeing-theory.brown.edu/', 'Interactive probability, distribution, inference, and regression intuition.', 10),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'website'::public.curated_course_resource_kind, 'Khan Academy Statistics and Probability', 'https://www.khanacademy.org/math/statistics-probability', 'Accessible lessons and practice for foundational probability and statistics.', 11),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'youtube'::public.curated_course_resource_kind, 'StatQuest with Josh Starmer', 'https://www.youtube.com/@statquest', 'Clear explanations of inference, regression, classification, validation, and statistical pitfalls.', 12),
  ('e60df9e4-b8fd-42ac-b3a6-0af75e393d9d', 'website'::public.curated_course_resource_kind, 'R, Python, Jupyter, and Excel', 'https://www.r-project.org/', 'Reproducible analysis, simulation, graphics, model validation, and transparent spreadsheet work. Also https://www.python.org/ and https://jupyter.org/.', 13);
